function main({data1}){
    // 解析JSON字符串
    const parsedData = JSON.parse(data1);

    // 检查数据结构是否存在
    if (!parsedData || !parsedData.result || !parsedData.result.parentingLeaveInfo) {
        return {
            result: {
                leaveUnit: undefined,
                leaveRemain: undefined
            }
        }
    }

    const leaveTotal = parsedData.result.parentingLeaveInfo.leaveTotal;
    const leaveUsed = parsedData.result.parentingLeaveInfo.leaveUsed;
    const leaveRemain = parsedData.result.parentingLeaveInfo.leaveRemain;

    return {

            leaveTotal: leaveTotal,
            leaveUsed: leaveUsed,
            leaveRemain: leaveRemain
    }
}

