function main({
  data1,
  mustFields = ['干部'],
  comboFields = [
     ['因公出国'],
    ['因私出国'],
    ['证件'],
    ['香港'],
    ['国外'],
    ['境外'],
    ['廉洁'],
    ['入职回避']
  ]
}) {
  // 检查是否包含所有 mustFields 中的关键词
  const hasAllMust = mustFields.every(keyword => data1.includes(keyword));

  // 检查是否满足任意一个 comboFields 组合
  const hasAnyCombo = comboFields.some(combo =>
    combo.every(keyword => data1.includes(keyword))
  );

  // 必须同时满足：全部 mustFields + 至少一个 combo
  const result = (hasAllMust && hasAnyCombo) ? '干部制度' : '正常制度';

  return {
    result: result
  };
}

